// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller) public {
        // The owner was set to address(this) during setUp. We prank as a random fuzzed caller.
        // The reference version must return address(this); the buggy version returns caller.
        vm.prank(caller);
        address reported = c.owner();
        assertTrue(reported == address(this));
    }
}

